"""Build the assigned officer-governed intersection scene through an adapter.

The adapter owns simulator resources. This module checks the reviewed geometry
and requests actors and controls; it never infers legal conduct from a script.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import isfinite
from typing import Mapping


@dataclass(frozen=True)
class Case:
    suffix: str
    other_phase: str
    other_station_m: float
    officer_directive: str


CASES = (
    Case("occupied_stop", "within", 0.0, "stop"),
    Case("occupied_proceed", "within", 0.0, "proceed"),
    Case("approaching_near_stop", "approaching", 8.0, "stop"),
    Case("approaching_near_proceed", "approaching", 8.0, "proceed"),
    Case("approaching_far_stop", "approaching", 35.0, "stop"),
    Case("approaching_far_proceed", "approaching", 35.0, "proceed"),
)


def _number(value):
    return type(value) in (int, float) and isfinite(value)


def _point(value):
    return isinstance(value, list) and len(value) == 2 and all(_number(x) for x in value)


def validate_site(site: Mapping) -> dict:
    if site.get("cell_id") != "C157964" or site.get("actor") != "motor_vehicle_driver":
        raise ValueError("reviewed site has wrong frozen cell or actor")
    if site.get("control") != "police_officer" or site.get("signal_controls") is not False:
        raise ValueError("reviewed officer control context missing")
    if site.get("layout") != "one_way_to_two_way_intersection" or site.get("maneuver") != "straight":
        raise ValueError("reviewed intersection layout or maneuver differs")
    if site.get("officer_controls_traffic") is not True:
        raise ValueError("active officer governance must be source-reviewed")
    for key in ("jurisdiction", "intersection_geometry", "entrance_controls",
                "officer_location", "officer_directive_visibility", "other_obligation",
                "ego_route", "other_route", "camera_sightlines"):
        digest = site.get(key + "_source_sha256")
        if not isinstance(digest, str) or len(digest) != 64:
            raise ValueError("reviewed source missing: " + key)
    route = site.get("ego_route_xy")
    if not isinstance(route, list) or len(route) < 2 or not all(_point(x) for x in route):
        raise ValueError("connected ego route missing")
    if not _point(site.get("other_spawn_xy")) or not _point(site.get("officer_spawn_xy")):
        raise ValueError("other participant or officer spawn missing")
    if not _number(site.get("officer_lateral_offset_limit_m")) or \
            site["officer_lateral_offset_limit_m"] < 0:
        raise ValueError("reviewed officer placement tolerance missing")
    if not _number(site.get("intersection_entry_station_m")) or \
            not _number(site.get("upstream_reference_station_m")) or \
            site["upstream_reference_station_m"] >= site["intersection_entry_station_m"]:
        raise ValueError("physical entry and upstream reference missing")
    if site.get("other_vehicle_obligated_to_stop_or_yield") is not False:
        raise ValueError("other participant obligation unreviewed")
    return dict(site)


def construct(adapter, site: Mapping, case: Case, officer_lateral_offset_m: float = 0.0):
    """Create original actors and distinct officer gestures; clean up on failure."""
    if case not in CASES:
        raise ValueError("unknown exact officer case")
    scene = validate_site(site)
    if not _number(officer_lateral_offset_m) or \
            not 0 <= officer_lateral_offset_m <= scene["officer_lateral_offset_limit_m"]:
        raise ValueError("officer offset exceeds source-reviewed placement")
    owned = []
    try:
        ego = adapter.spawn_vehicle(scene["ego_route_xy"][0], "ego")
        if ego is None:
            raise ValueError("ego spawn failed")
        owned.append(ego)
        other = adapter.spawn_vehicle(scene["other_spawn_xy"], "other")
        if other is None:
            raise ValueError("other vehicle spawn failed")
        owned.append(other)
        officer_position = [scene["officer_spawn_xy"][0],
                            scene["officer_spawn_xy"][1] + officer_lateral_offset_m]
        officer = adapter.spawn_officer(officer_position)
        if officer is None:
            raise ValueError("officer spawn failed")
        owned.append(officer)
        adapter.set_ego_route(ego, scene["ego_route_xy"])
        adapter.set_other_phase(other, case.other_phase, case.other_station_m)
        adapter.set_officer_directive(officer, case.officer_directive)
        return {"case_suffix": case.suffix, "actors": tuple(owned),
                "officer_directive_requested": case.officer_directive,
                "other_phase_requested": case.other_phase,
                "other_station_requested_m": case.other_station_m,
                "legal_judgment": None}
    except Exception:
        for actor in reversed(owned):
            adapter.destroy(actor)
        raise

"""Saved-only source admission for a reviewed officer-control exception interval.

An officer's presence alone does not establish that the officer controls traffic.
The result is an engineering context measurement, never a legal verdict.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

ASSIGNMENT = "testing__C157964__NRS-484B-257-2__motor_vehicle_driver"


def source_bytes(root: Path, ref: dict) -> bytes:
    if not isinstance(ref, dict) or not isinstance(ref.get("path"), str):
        raise ValueError("source path required")
    relative = Path(ref["path"])
    if relative.is_absolute() or ".." in relative.parts:
        raise ValueError("source path must remain beneath source root")
    raw = (root / relative).read_bytes()
    if hashlib.sha256(raw).hexdigest() != ref.get("sha256"):
        raise ValueError("original source hash differs")
    return raw


def source(root: Path, ref: dict) -> dict:
    return json.loads(source_bytes(root, ref))


def measure(packet: dict, root: Path) -> dict:
    if packet.get("assignment_id") != ASSIGNMENT or packet.get("cell_id") != "C157964":
        raise ValueError("assignment/cell differs")
    if packet.get("law_id") != "NRS-484B-257-2" or packet.get("actor") != "motor_vehicle_driver":
        raise ValueError("law/actor differs")
    result = source(root, packet.get("native_result"))
    frames = source(root, packet.get("frame_map"))
    review = source(root, packet.get("officer_review"))
    video = source_bytes(root, packet.get("original_video"))
    if result.get("source_kind") != "original_native" or result.get("assignment_id") != ASSIGNMENT:
        raise ValueError("sealed original Native result required")
    if result.get("recording_id") != packet.get("recording_id"):
        raise ValueError("recording identity differs")
    if not isinstance(frames, list) or len(frames) != 900:
        raise ValueError("complete 900-frame original map required")
    if any(row.get("frame") != index or row.get("elapsed_s") != index / 20
           for index, row in enumerate(frames)):
        raise ValueError("original frame map is not contiguous 20 Hz")
    if review.get("source_kind") != "original_independent_review":
        raise ValueError("independent original officer review required")
    if review.get("recording_id") != packet["recording_id"]:
        raise ValueError("officer review recording differs")
    if not review.get("reviewer_id") or review.get("source_video_sha256") != hashlib.sha256(video).hexdigest():
        raise ValueError("officer review provenance missing")
    interval = review.get("crossing_interval_frames")
    if not isinstance(interval, list) or len(interval) != 2 or not all(isinstance(x, int) and not isinstance(x, bool) for x in interval):
        raise ValueError("reviewed crossing frame interval required")
    first, last = interval
    if not 0 <= first <= last < len(frames):
        raise ValueError("reviewed crossing interval outside original capture")
    state = review.get("officer_controlling_traffic")
    if state is not None and type(state) is not bool:
        raise ValueError("reviewed control state invalid")
    if review.get("officer_visible") is not True and state is True:
        raise ValueError("controlling officer lacks original visibility")
    return {
        "format": "worker-officer-control-context-measurement",
        "assignment_id": ASSIGNMENT,
        "recording_id": packet["recording_id"],
        "crossing_interval_frames": interval,
        "officer_visible": review.get("officer_visible") is True,
        "officer_controlling_traffic": state,
        "exception_context": "observed_officer_control" if state is True else
                             "officer_present_not_controlling" if state is False else "unverified",
        "source_sha256": {key: packet[key]["sha256"] for key in
                          ("native_result", "frame_map", "officer_review", "original_video")},
        "legal_verdict": None,
    }
